#include "md_grid.h"

void md(
    int32_t n_points[blockSide][blockSide][blockSide],
    dvector_t force[blockSide][blockSide][blockSide][densityFactor],
    dvector_t position[blockSide][blockSide][blockSide][densityFactor]) {

    int i, j, k, l;
    int ni, nj, nk;
    int ii, jj, kk;
    int q;

    for (i = 0; i < blockSide; i++) {
        for (j = 0; j < blockSide; j++) {
            for (k = 0; k < blockSide; k++) {
                int32_t point_count = n_points[i][j][k];
                for (l = 0; l < point_count; l++) {
                    dvector_t* p_pos = &position[i][j][k][l];
                    dvector_t* p_force = &force[i][j][k][l];

                    for (ni = -1; ni <= 1; ni++) {
                        for (nj = -1; nj <= 1; nj++) {
                            for (nk = -1; nk <= 1; nk++) {
                                ii = i + ni;
                                jj = j + nj;
                                kk = k + nk;

                                if (ii < 0 || ii >= blockSide ||
                                    jj < 0 || jj >= blockSide ||
                                    kk < 0 || kk >= blockSide) {
                                    continue;
                                }

                                int32_t neighbor_count = n_points[ii][jj][kk];
                                for (q = 0; q < neighbor_count; q++) {
                                    dvector_t* q_pos = &position[ii][jj][kk][q];

                                    TYPE dx = q_pos->x - p_pos->x;
                                    TYPE dy = q_pos->y - p_pos->y;
                                    TYPE dz = q_pos->z - p_pos->z;

                                    TYPE r2 = dx*dx + dy*dy + dz*dz;
                                    if (r2 == 0.0) {
                                        continue;
                                    }

                                    TYPE r2inv = 1.0 / r2;
                                    TYPE r6inv = r2inv * r2inv * r2inv;
                                    TYPE f = (12.0 * lj1 * r6inv * r6inv - 6.0 * lj2 * r6inv) * r2inv;

                                    p_force->x += f * dx;
                                    p_force->y += f * dy;
                                    p_force->z += f * dz;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
```

